var routes = {
  'alarm': 'tb.nic.candidate.alarm.v1',
  'device_state': 'tb.nic.candidate.device-state.v1',
  'lifecycle': 'tb.nic.candidate.lifecycle.v1',
  'ota': 'tb.nic.candidate.ota.v1'
};
var candidateType = msg['candidateType'];
if (candidateType == null) {
  var err = {'error': 'missing_candidate_type', 'candidateType': 'dlt'};
  return {msg: err, metadata: metadata, msgType: 'Failure'};
}
var topic = routes[candidateType];
if (topic == null) {
  var err2 = {'error': 'unknown_candidate_type', 'value': candidateType, 'candidateType': 'dlt'};
  return {msg: err2, metadata: metadata, msgType: 'Failure'};
}
metadata['kafkaTopic'] = topic;
return {msg: msg, metadata: metadata, msgType: msgType};

var preMapped = msg.mappedAlarms;
if (preMapped != null && preMapped.size() > 0) {
    var alarm = preMapped[preMapped.size() - 1];
    var canonical = alarm.canonicalAlarm;
    var parts = canonical.split('\\.'); // Escape the dot for split

    if (parts.size() >= 2) {
        metadata.alarmFamily = parts[0] + '.' + parts[1];
    } else {
        metadata.alarmFamily = 'unknown';
    }
}
return {msg: msg, metadata: metadata, msgType: msgType};

var alarm = msg.mappedAlarms[msg.mappedAlarms.size() - 1];
var isClear = (alarm.state == 0);

var alarmPayload = [
    'alarmType': alarm.canonicalAlarm,
    'alarmSeverity': 'MAJOR',
    'alarmStatus': alarm.lifecycleState,
    'alarmDetails': [
        'source': 'rulechain_failsafe',
        'sourceCode': alarm.sourceCode,
        'sourceEventTs': alarm.sourceEventTs
    ]
];

return {msg: alarmPayload, metadata: metadata, msgType: isClear ? 'ALARM_CLEAR' : 'ALARM_UPSERT'};

