configuration.tbelScript:
// Define the map of who owns what
var authorityMap = [
  'backend.hes': 'rulechain',
  'modem.network': 'profile',
  'power.mains': 'profile',
  'uart.meter': 'rulechain'
];

var authority = authorityMap[metadata.alarmFamily] ?: 'profile';
metadata.authority = authority;

// If rulechain is the primary authority, go straight to "Upsert"
if (authority == 'rulechain') {
    return ['RulechainPrimary'];
}

// If profile is authority, we need to check if it actually set the alarm
return ['CheckProfileStatus'];

var activeAlarms = msg['device.runtime.active_alarms']; // Ensure this key is available
var currentCode = msg.mappedAlarms[msg.mappedAlarms.size() - 1].sourceCode;

if (activeAlarms != null) {
    for (var code : activeAlarms) {
        if (('' + code) == ('' + currentCode)) {
            return false; // Alarm already set by profile, Filter = False
        }
    }
}
return true; // Alarm NOT set by profile, Rule Chain should take over

